INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13255, 'koKR', 'Dowód zgonu: Herold Volazj', 'Nerubianie z Ahn\'kahet, próbując umknąć przed inwazją Plagi, dokopali się zbyt głęboko. Zbliżyli się za bardzo do Przedwiecznego spoczywającego pod Północną Granią.$B$BPrzebudzony Przedwieczny wysłał przeciw nim swoje obłąkane stwory i nerubianie znaleźli się, jak to mówią, między młotem a kowadłem.$B$BPrzywódca sił Przedwiecznych, herold Volazj, jest jedną z koszmarnych istot zwanych Beztwarzowymi. Połóż mu kres i przynieś mi jego zwiędły mózg.$B$BTylko proszę, postaraj się nie postradać zmysłów.', 'Arcymag Lan\'dalock w Dalaranie chce, abyś $gwrócił:wróciła; ze zwiędłym mózgiem Beztwarzowego.$B$BTo zadanie można ukończyć wyłącznie na poziomie heroicznym.', '', 'Wróć do arcymaga Lan\'dalocka w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13255, 'koKR', '<Arcymag ostrożnie przygląda się mózgowi.>$b$bTeraz, gdy o tym myślę, nie jestem pewien, czy przebywanie tak blisko tego czegoś jest bezpieczne. Mówisz, że to wciąż żyje?$b$b<Kręci głową.>$b$bMamy w cytadeli miejsce na takie rzeczy. Dopilnuję, by jeden z moich uczniów natychmiast je tam zaniósł.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13255, 'koKR', '$n? Wciąż przy zdrowych zmysłach?', 0);
